from openai import OpenAI
import os

def select_model_resource():
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    models = client.models.list()
    # For this example, we'll just return the ID of the first available model that is a chat completion model
    for model in models.data:
        if "gpt" in model.id:
            return model.id
    return None

from openai import OpenAI
import os

def collect_model_metadata(prompt: str, model_name: str = "gpt-4o"):
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    response = client.chat.completions.create(
        model=model_name,
        messages=[{"role": "user", "content": prompt}]
    )
    return {
        "output": response.choices[0].message.content,
        "usage": response.usage.model_dump(),
        "model_id": response.model
    }

from openai import OpenAI
import os

def get_openai_client():
    return OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

from typing import Optional, Dict, Any

class ModelRequest:
    def __init__(self, prompt: str, model: str = "gpt-4o", temperature: float = 0.7):
        self.prompt = prompt
        self.model = model
        self.temperature = temperature

class ModelResponse:
    def __init__(self, content: str, model_id: str, usage: Optional[Dict[str, Any]] = None):
        self.content = content
        self.model_id = model_id
        self.usage = usage

    def normalize(self):
        return {
            "text": self.content,
            "model": self.model_id,
            "token_usage": self.usage
        }
